import type { ImgHTMLAttributes } from "react";

export interface YourMealLogoProps {
  size?: number | string;
  showWordmark?: boolean;
  className?: string;
  variant?: "light" | "dark" | "auto";
}

const OFFICIAL_MARK_DARK = "data:image/png;base64,";
const OFFICIAL_MARK_LIGHT = "data:image/png;base64,";

/**
 * Official YourMeal OS Geometric Brandmark (Isotipo)
 * High-definition inline vector/raster rendering with automatic dark/light theme support.
 * Guaranteed 0ms load time and immune to browser caching issues.
 */
export function YourMealMark({
  size = 36,
  className = "",
  variant = "auto",
  ...props
}: YourMealLogoProps & Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "size">) {
  const numericSize = typeof size === "number" ? size : parseInt(size as string, 10) || 36;

  if (variant === "dark") {
    return (
      <img
        src={OFFICIAL_MARK_LIGHT}
        alt="YourMeal OS"
        width={numericSize}
        height={numericSize}
        style={{ width: `${numericSize}px`, height: `${numericSize}px` }}
        className={`shrink-0 object-contain ${className}`}
        decoding="sync"
        loading="eager"
        {...props}
      />
    );
  }

  if (variant === "light") {
    return (
      <img
        src={OFFICIAL_MARK_DARK}
        alt="YourMeal OS"
        width={numericSize}
        height={numericSize}
        style={{ width: `${numericSize}px`, height: `${numericSize}px` }}
        className={`shrink-0 object-contain ${className}`}
        decoding="sync"
        loading="eager"
        {...props}
      />
    );
  }

  // Auto responsive for light / dark theme
  return (
    <div
      style={{ width: `${numericSize}px`, height: `${numericSize}px` }}
      className={`relative shrink-0 inline-flex items-center justify-center ${className}`}
    >
      <img
        src={OFFICIAL_MARK_DARK}
        alt="YourMeal OS"
        width={numericSize}
        height={numericSize}
        className="w-full h-full object-contain dark:hidden"
        decoding="sync"
        loading="eager"
        {...props}
      />
      <img
        src={OFFICIAL_MARK_LIGHT}
        alt="YourMeal OS"
        width={numericSize}
        height={numericSize}
        className="w-full h-full object-contain hidden dark:block"
        decoding="sync"
        loading="eager"
        {...props}
      />
    </div>
  );
}

/**
 * Official YourMeal OS Full Logo (Mark + Wordmark)
 */
export function YourMealLogo({
  size = 36,
  showWordmark = true,
  className = "",
  variant = "auto",
}: YourMealLogoProps) {
  return (
    <div className={`inline-flex items-center gap-3 ${className}`}>
      <YourMealMark size={size} variant={variant} />
      {showWordmark && (
        <div className="flex flex-col text-left">
          <span className="font-display font-black text-base tracking-tight text-foreground leading-none">
            YourMeal <span className="text-primary font-black">OS</span>
          </span>
          <span className="text-[10px] text-muted-foreground font-semibold uppercase tracking-wider block mt-0.5">
            Operaciones Gastronómicas
          </span>
        </div>
      )}
    </div>
  );
}